      solution: "def classify(status):\n    kind = status // 100\n    if kind == 2:\n        return \"success\"\n    if kind == 3:\n        return \"redirect\"\n    if kind == 4:\n        return \"client error\"\n    if kind == 5:\n        return \"server error\"\n    raise ValueError(f\"Unknown status {status}\")",
